-- =============================================================================
-- FUTURESELITE — TOUT EN UN
-- =============================================================================
-- Un seul copier-coller. Aucun prerequis. Toutes les commandes sont
-- idempotentes : rejouable sans casse.
--
-- OU LE COLLER : supabase.com -> ton projet -> SQL Editor -> New query
--                -> coller -> Run.
--
-- Ce fichier remplit AUSSI les colonnes editoriales JSONB (journey, key_rules,
-- program_guide, cost_timeline, verdict_card, pros, cons). Ce sont elles qui
-- donnent son epaisseur a la page : une section disparait quand sa colonne est
-- NULL. Sans elles, la page reste vide meme apres un import reussi.
-- =============================================================================


-- 1. SAUVEGARDE — lis cette sortie avant de continuer
select * from prop_firms where slug = 'futureselite';
select * from prop_firm_challenges where firm_slug = 'futureselite';


-- 2. Colonnes necessaires (sans effet si elles existent deja)
alter table prop_firms add column if not exists price_currency text default 'USD';
alter table prop_firms add column if not exists data_verified_at timestamptz;
alter table prop_firms add column if not exists data_verified_by text;
alter table prop_firms add column if not exists source_url text;
alter table prop_firms add column if not exists rating_checked_at timestamptz;
alter table prop_firms add column if not exists discount_status text;
alter table prop_firms add column if not exists discount_starts_at timestamptz;
alter table prop_firms add column if not exists max_profit_split integer;
alter table prop_firms add column if not exists translations jsonb;
alter table prop_firms add column if not exists restricted_countries text[];


-- 3. La firme : identite, contenu editorial, listes
update prop_firms set
  name                 = 'FuturesElite',
  category_badge       = 'Futures only',
  headline             = 'Four routes to a funded futures account, evaluation or instant',
  verdict              = 'A futures prop firm built around choice: Elite and Prime run classic evaluations, Nitro targets faster payouts, and Instant funds you the day you buy. Each program carries its own loss limits, consistency rule and payout conditions, so the right one depends less on price than on how you actually trade.',
  description          = 'FuturesElite sells simulated futures accounts across four programs. Elite and Prime are evaluation routes with a one-time fee and no deadline to pass. Nitro and Instant shorten or remove the evaluation entirely, Instant funding you from purchase with no objective to reach. All four settle at a 90% profit split, and payouts can be requested daily once an account is funded.

It suits futures traders who already have a method and want to choose the rule set that fits it, rather than accept one. Loss limits are dollar amounts rather than percentages, drawdown is calculated at the end of the day on the evaluation programs, and seven platforms are available including Tradovate, NinjaTrader and Quantower.

The caveat matters more than the pricing. Quantum SRL holds no financial regulator licence, and every account is simulated: performance is hypothetical throughout. The live trading program exists but is a risk-team decision, not an entitlement earned at a fixed number of payouts.',
  website_url          = 'https://futureselite.com',
  affiliate_url        = 'https://app.futureselite.com/dashboard/choose-plan?aff=AFF5465384&coupon=scanned',
  headquarters         = 'Corso G. Matteotti 61, Latina 04100, Italy',
  country              = 'Italy',
  price_currency       = 'USD',
  is_regulated         = false,
  regulation_details   = 'Quantum SRL, Corso G. Matteotti 61, Latina 04100, Italy, no. 03095010595. No financial regulator licence. Demo accounts, hypothetical performance.',
  profit_split         = 90,
  max_profit_split     = 90,
  min_price            = 95,
  max_price            = 353,
  is_futures           = true,
  drawdown_type        = 'End of day',
  time_limit           = 'No time limit',
  payout_frequency     = 'on demand, daily once funded',
  source_url           = 'https://futureselite.com',
  logo_url             = 'https://www.google.com/s2/favicons?domain=futureselite.com&sz=128',
  platforms            = 'Tradovate, NinjaTrader, Quantower, ATAS, Volumetrica, DeepDOM, DeepCharts',
  assets               = '{"Futures"}'::text[],
  included_items       = '{"Trading journal and analytics dashboard","No activation fee on the funded account","Seven platforms to choose from"}'::text[],
  pros                 = '{"90% profit split on the Elite programme","End-of-day drawdown, with no daily loss limit at all","No consistency rule once funded","No activation fee to unlock the funded account","Payouts available every day once funded","Bundle discounts: the fifth account is free"}'::text[],
  cons                 = '{"No financial regulator licence","Demo accounts, hypothetical performance","3 minimum trading days in evaluation, 6 once funded","Per-request payout cap, from $1,000 to $3,000 by account size","The Nitro, Prime and Instant price lists are not public"}'::text[],
  special_features     = '{"90% profit split on the Elite programme","End-of-day drawdown, no daily loss limit","No consistency rule once funded","No activation fee on the funded account","Bundle discounts: the fifth account is free","Instant accounts available, with no evaluation"}'::text[],
  verdict_card         = '{"title":"Who it suits, and who it does not","body":"FuturesElite bets on generous terms once you are funded: a 90% split, no consistency rule, daily payouts. In exchange, the firm is young and is a proprietary trading company rather than a regulated broker.","points":["A high split and frequent payouts, with no waiting period","An evaluation with no daily loss limit, which leaves room to breathe","A funded account that opens with no activation fee","The option to stack up to ten accounts in parallel"]}'::jsonb,
  program_guide        = '{"title":"Four programmes","intro":"Four programmes are sold: Elite, Nitro, Prime and Instant. Their prices and rules differ, and the configurator above shows each one.","options":[{"name":"Elite","badge":"Public pricing","summary":"A one-step evaluation, an end-of-day drawdown, no daily loss limit, and a 90% split once funded.","points":["5% profit target","No daily loss limit","3 minimum trading days","No activation fee"]}]}'::jsonb,
  key_rules            = '{"title":"The rules that decide it","intro":"What genuinely sets FuturesElite apart from other futures firms.","rules":[{"title":"No daily loss limit","detail":"Neither during the evaluation nor once funded. Risk is bounded by the Maximum Loss Limit alone, recalculated at the end of each day. That is the firm’s headline argument, not a missing figure."},{"title":"End-of-day drawdown","detail":"The limit updates once a day on the closing balance, not continuously. A position sitting at a floating loss therefore does not trip the limit until the day closes."},{"title":"No consistency rule once funded","detail":"The rule applies during the evaluation and then disappears on the funded account. The sales page shows two figures side by side, 40% and 50%, without saying which applies: to be confirmed with the partner."},{"title":"No activation fee","detail":"Passing the evaluation is enough to open the funded account. Reset fees do exist: $79 to $229 by size."}],"more":["Payouts available every day once funded","6 minimum trading days before a payout","No profit buffer required","Seven platforms to choose from, including Tradovate and NinjaTrader","The fifth account in a bundle is free"]}'::jsonb,
  journey              = '{"title":"What happens after you pay","intro":"A single evaluation step, then the funded account opens immediately.","steps":[{"title":"Evaluation","detail":"Hit the profit target without breaching the Maximum Loss Limit, across at least 3 trading days. No time limit."},{"title":"Funded account","detail":"Opened as soon as you pass, with no activation fee. The consistency rule disappears at this stage."},{"title":"Payouts","detail":"Available every day, after 6 trading days, within the per-request cap: $1,000 on a 25K, up to $3,000 on a 150K."},{"title":"Stacking accounts","detail":"Elite counts towards a shared cap of 5 funded accounts across Elite, Custom, Instant and Nitro. The overall ceiling is 10 active funded accounts, and Nitro alone is limited to 3. Buying a bundle does not raise those limits."}]}'::jsonb,
  cost_timeline        = '{"title":"What you will pay","intro":"The costs do not all land at the same moment.","steps":[{"label":"At purchase","title":"One-off fee","detail":"From $95 for a 25K to $353 for a 150K, before discount. No subscription."},{"label":"On failure","title":"Optional reset","detail":"From $79 on a 25K to $229 on a 150K. Starting over is never compulsory."},{"label":"On passing","title":"No activation fee","detail":"The funded account opens with no further payment."},{"label":"At payout","title":"Per-request cap","detail":"From $1,000 to $3,000 by account size, with 90% for you."}]}'::jsonb,
  translations         = '{"fr":{"category_badge":"Futures uniquement","headline":"Quatre voies vers un compte futures finance, evaluation ou immediat","verdict":"Une firme futures construite autour du choix : Elite et Prime proposent des evaluations classiques, Nitro vise des paiements plus rapides, et Instant finance des l’achat. Chaque programme porte ses propres limites de perte, sa regle de regularite et ses conditions de retrait — le bon depend moins du prix que de votre facon de trader.","description":"FuturesElite vend des comptes futures simules repartis en quatre programmes. Elite et Prime sont des evaluations a frais unique, sans date limite pour reussir. Nitro et Instant raccourcissent ou suppriment l’evaluation, Instant vous financant des l’achat sans objectif a atteindre. Les quatre aboutissent a 90 % de partage des profits, avec des retraits possibles chaque jour une fois le compte finance.\n\nElle convient aux traders futures qui ont deja une methode et veulent choisir le jeu de regles qui lui correspond, plutot que de le subir. Les limites de perte sont des montants en dollars et non des pourcentages, le drawdown se calcule en fin de journee sur les programmes d’evaluation, et sept plateformes sont disponibles, dont Tradovate, NinjaTrader et Quantower.\n\nLa reserve compte plus que le tarif. Quantum SRL ne detient aucune licence de regulateur financier, et tous les comptes sont simules : les performances restent hypothetiques du debut a la fin. Le programme de trading live existe mais releve d’une decision de l’equipe de risque, pas d’un droit acquis apres un nombre fixe de retraits.","headquarters":"Corso G. Matteotti 61, Latina 04100, Italie","regulation_details":"Quantum SRL, Corso G. Matteotti 61, Latina 04100, Italie, n° 03095010595. Aucune licence de régulateur financier. Comptes de démonstration, performances hypothétiques.","drawdown_type":"Fin de journée","time_limit":"Aucune limite de temps","payout_frequency":"sur demande, chaque jour une fois financé","assets":["Futures"],"included_items":["Journal de trading et tableau de bord analytique","Aucun frais d’activation du compte financé","Sept plateformes au choix"],"pros":["Partage des profits à 90 % sur le programme Elite","Drawdown de fin de journée, sans aucune limite de perte journalière","Aucune règle de régularité une fois financé","Aucun frais d’activation pour débloquer le compte financé","Retrait possible chaque jour une fois financé","Remises par lot : le cinquième compte est offert"],"cons":["Aucune licence de régulateur financier","Comptes de démonstration, performances hypothétiques","3 jours de trading minimum en évaluation, 6 une fois financé","Plafond de retrait par demande, de 1 000 à 3 000 $ selon la taille","Les grilles Nitro, Prime et Instant ne sont pas publiques"],"special_features":["Partage des profits à 90 % sur le programme Elite","Drawdown de fin de journée, aucune limite de perte journalière","Aucune règle de régularité une fois financé","Aucun frais d’activation du compte financé","Remises par lot : le cinquième compte est offert","Comptes Instant disponibles, sans évaluation"],"verdict_card":{"title":"Pour qui, et pour qui pas","body":"FuturesElite mise sur des conditions généreuses une fois financé : 90 % de partage, aucune règle de régularité, retrait quotidien. En échange, la firme est jeune et reste une société de trading propriétaire, pas un courtier régulé.","points":["Un partage élevé et des retraits fréquents, sans attendre une échéance","Une évaluation sans limite de perte journalière, qui laisse respirer","Un compte financé qui s’ouvre sans frais d’activation","Un plafond de 10 comptes financés actifs, dont 5 au maximum partagés entre Elite, Custom, Instant et Nitro"]},"program_guide":{"title":"Quatre programmes","intro":"Quatre programmes sont vendus : Elite, Nitro, Prime et Instant. Leurs prix et leurs règles diffèrent, et le configurateur ci-dessus les détaille un par un.","options":[{"name":"Elite","badge":"Grille publique","summary":"Une évaluation en une étape, un drawdown de fin de journée, aucune perte journalière, et 90 % de partage une fois financé.","points":["Objectif de 5 % du capital","Aucune limite de perte journalière","3 jours de trading minimum","Aucun frais d’activation"]}]},"key_rules":{"title":"Les règles qui décident","intro":"Ce qui distingue vraiment FuturesElite des autres firmes futures.","rules":[{"title":"Aucune limite de perte journalière","detail":"Ni pendant l’évaluation, ni une fois financé. Le risque est encadré par la seule Maximum Loss Limit, recalculée en fin de journée. C’est l’argument principal de la firme, pas une donnée manquante."},{"title":"Drawdown de fin de journée","detail":"La limite se met à jour une fois par jour sur le solde de clôture, pas en continu. Une position en perte latente ne déclenche donc pas la limite tant que la journée n’est pas close."},{"title":"Aucune règle de régularité une fois financé","detail":"La règle s’applique pendant l’évaluation puis disparaît sur le compte financé. La page de vente affiche deux valeurs côte à côte, 40 % et 50 %, sans préciser laquelle s’applique : à confirmer auprès du partenaire."},{"title":"Aucun frais d’activation","detail":"Passer l’évaluation suffit à ouvrir le compte financé. Les frais de reset, eux, existent : de 79 à 229 $ selon la taille."}],"more":["Retrait possible chaque jour une fois financé","6 jours de trading minimum avant un retrait","Aucun buffer de profit exigé","Sept plateformes au choix, dont Tradovate et NinjaTrader","Le cinquième compte d’un lot est offert"]},"journey":{"title":"Ce qui se passe après le paiement","intro":"Une seule étape d’évaluation, puis le compte financé s’ouvre immédiatement.","steps":[{"title":"Évaluation","detail":"Atteindre l’objectif de profit sans franchir la Maximum Loss Limit, sur au moins 3 jours de trading. Aucune limite de temps."},{"title":"Compte financé","detail":"Ouvert dès la validation, sans frais d’activation. La règle de régularité disparaît à ce stade."},{"title":"Retraits","detail":"Possibles chaque jour, après 6 jours de trading, dans la limite du plafond par demande : 1 000 $ sur un 25K, jusqu’à 3 000 $ sur un 150K."},{"title":"Cumul de comptes","detail":"Elite plafonne à 5 comptes financés. En empilant un programme de même taille, jusqu’à 10 comptes en parallèle."}]},"cost_timeline":{"title":"Ce que vous paierez","intro":"Les coûts n’arrivent pas tous au même moment.","steps":[{"label":"À l’achat","title":"Frais unique","detail":"De 95 $ pour un 25K à 353 $ pour un 150K, hors remise. Aucun abonnement."},{"label":"En cas d’échec","title":"Reset optionnel","detail":"De 79 $ sur un 25K à 229 $ sur un 150K. Reprendre à zéro n’est jamais obligatoire."},{"label":"À la validation","title":"Aucun frais d’activation","detail":"Le compte financé s’ouvre sans paiement supplémentaire."},{"label":"Au retrait","title":"Plafond par demande","detail":"De 1 000 à 3 000 $ selon la taille du compte, avec 90 % pour vous."}]}},"de":{"headquarters":"Corso G. Matteotti 61, Latina 04100, Italien","regulation_details":"Quantum SRL, Corso G. Matteotti 61, Latina 04100, Italien, Nr. 03095010595. Keine Lizenz einer Finanzaufsicht. Demokonten, hypothetische Ergebnisse.","drawdown_type":"Tagesende","time_limit":"Keine Zeitbegrenzung","payout_frequency":"auf Anfrage, täglich nach der Finanzierung","assets":["Futures"],"included_items":["Handelstagebuch und Analyse-Dashboard","Keine Aktivierungsgebühr für das finanzierte Konto","Sieben Plattformen zur Auswahl"],"pros":["90 % Gewinnbeteiligung beim Elite-Programm","Drawdown zum Tagesende, ganz ohne Tagesverlustlimit","Keine Konsistenzregel nach der Finanzierung","Keine Aktivierungsgebühr für das finanzierte Konto","Tägliche Auszahlungen nach der Finanzierung","Bündelrabatte: Das fünfte Konto ist gratis"],"cons":["Keine Lizenz einer Finanzaufsicht","Demokonten, hypothetische Ergebnisse","3 Mindesthandelstage in der Evaluierung, 6 nach der Finanzierung","Auszahlungsobergrenze je Antrag, 1.000 $ bis 3.000 $ je nach Kontogröße","Die Preislisten für Nitro, Prime und Instant sind nicht öffentlich"],"special_features":["90 % Gewinnbeteiligung beim Elite-Programm","Drawdown zum Tagesende, kein Tagesverlustlimit","Keine Konsistenzregel nach der Finanzierung","Keine Aktivierungsgebühr für das finanzierte Konto","Bündelrabatte: Das fünfte Konto ist gratis","Instant-Konten verfügbar, ohne Evaluierung"],"verdict_card":{"title":"Für wen es passt — und für wen nicht","body":"FuturesElite setzt auf großzügige Bedingungen nach der Finanzierung: 90 % Beteiligung, keine Konsistenzregel, tägliche Auszahlung. Dafür ist der Anbieter jung, unreguliert und veröffentlicht nur eine seiner vier Preislisten.","points":["Eine hohe Beteiligung und häufige Auszahlungen, ohne Wartefrist","Eine Evaluierung ohne Tagesverlustlimit, die Luft zum Atmen lässt","Ein finanziertes Konto, das ohne Aktivierungsgebühr öffnet","Die Möglichkeit, bis zu zehn Konten parallel zu stapeln"]},"program_guide":{"title":"Das Elite-Programm","intro":"Elite ist das einzige Programm mit öffentlicher Preisliste. Nitro, Prime und Instant gibt es an der Kasse, ihre Preise werden aber nicht gezeigt.","options":[{"name":"Elite","badge":"Öffentliche Preise","summary":"Eine einstufige Evaluierung, ein Drawdown zum Tagesende, kein Tagesverlustlimit und 90 % Beteiligung nach der Finanzierung.","points":["5 % Gewinnziel","Kein Tagesverlustlimit","3 Mindesthandelstage","Keine Aktivierungsgebühr"]}]},"key_rules":{"title":"Die Regeln, die entscheiden","intro":"Was FuturesElite wirklich von anderen Futures-Anbietern unterscheidet.","rules":[{"title":"Kein Tagesverlustlimit","detail":"Weder während der Evaluierung noch nach der Finanzierung. Das Risiko wird allein durch die Maximum Loss Limit begrenzt, die am Tagesende neu berechnet wird. Das ist das Hauptargument des Anbieters, keine fehlende Angabe."},{"title":"Drawdown zum Tagesende","detail":"Das Limit aktualisiert sich einmal täglich auf den Schlusssaldo, nicht laufend. Eine Position im schwebenden Verlust löst das Limit daher erst nach Tagesschluss aus."},{"title":"Keine Konsistenzregel nach der Finanzierung","detail":"Die Regel gilt während der Evaluierung und entfällt auf dem finanzierten Konto. Die Verkaufsseite zeigt zwei Werte nebeneinander, 40 % und 50 %, ohne zu sagen, welcher gilt: beim Partner zu klären."},{"title":"Keine Aktivierungsgebühr","detail":"Das Bestehen der Evaluierung genügt, um das finanzierte Konto zu eröffnen. Reset-Gebühren gibt es sehr wohl: 79 $ bis 229 $ je nach Größe."}],"more":["Tägliche Auszahlungen nach der Finanzierung","6 Mindesthandelstage vor einer Auszahlung","Kein Gewinnpuffer erforderlich","Sieben Plattformen zur Auswahl, darunter Tradovate und NinjaTrader","Das fünfte Konto im Bündel ist gratis"]},"journey":{"title":"Was nach der Zahlung passiert","intro":"Eine einzige Evaluierungsstufe, danach öffnet das finanzierte Konto sofort.","steps":[{"title":"Evaluierung","detail":"Das Gewinnziel erreichen, ohne die Maximum Loss Limit zu verletzen, an mindestens 3 Handelstagen. Keine Zeitbegrenzung."},{"title":"Finanziertes Konto","detail":"Wird bei Bestehen eröffnet, ohne Aktivierungsgebühr. Die Konsistenzregel entfällt an dieser Stelle."},{"title":"Auszahlungen","detail":"Täglich möglich, nach 6 Handelstagen, innerhalb der Obergrenze je Antrag: 1.000 $ bei einem 25K, bis 3.000 $ bei einem 150K."},{"title":"Konten stapeln","detail":"Elite zählt zu einer gemeinsamen Obergrenze von 5 finanzierten Konten mit Custom, Instant und Nitro. Insgesamt sind 10 aktive finanzierte Konten möglich, Nitro allein höchstens 3. Ein Bundle-Kauf hebt diese Grenzen nicht an."}]},"cost_timeline":{"title":"Was Sie zahlen werden","intro":"Die Kosten fallen nicht alle zum selben Zeitpunkt an.","steps":[{"label":"Beim Kauf","title":"Einmalige Gebühr","detail":"Von 95 $ für ein 25K bis 353 $ für ein 150K, vor Rabatt. Kein Abonnement."},{"label":"Bei Nichtbestehen","title":"Optionaler Reset","detail":"Von 79 $ bei einem 25K bis 229 $ bei einem 150K. Neu anfangen ist nie Pflicht."},{"label":"Beim Bestehen","title":"Keine Aktivierungsgebühr","detail":"Das finanzierte Konto wird ohne weitere Zahlung eröffnet."},{"label":"Bei Auszahlung","title":"Obergrenze je Antrag","detail":"Von 1.000 $ bis 3.000 $ je nach Kontogröße, mit 90 % für Sie."}]}},"es":{"headquarters":"Corso G. Matteotti 61, Latina 04100, Italia","regulation_details":"Quantum SRL, Corso G. Matteotti 61, Latina 04100, Italia, n.º 03095010595. Sin licencia de ningún regulador financiero. Cuentas demo, resultados hipotéticos.","drawdown_type":"Fin del día","time_limit":"Sin límite de tiempo","payout_frequency":"a petición, a diario una vez financiado","assets":["Futuros"],"included_items":["Diario de trading y panel de analítica","Sin comisión de activación de la cuenta financiada","Siete plataformas a elegir"],"pros":["90 % de reparto en el programa Elite","Drawdown al cierre del día, sin ningún límite de pérdida diaria","Sin regla de consistencia una vez financiado","Sin comisión de activación de la cuenta financiada","Cobros disponibles cada día una vez financiado","Descuentos por lote: la quinta cuenta es gratis"],"cons":["Sin licencia de ningún regulador financiero","Cuentas demo, resultados hipotéticos","3 días mínimos de trading en evaluación, 6 una vez financiado","Tope de cobro por solicitud, de 1.000 $ a 3.000 $ según el tamaño","Las tarifas de Nitro, Prime e Instant no son públicas"],"special_features":["90 % de reparto en el programa Elite","Drawdown al cierre del día, sin límite de pérdida diaria","Sin regla de consistencia una vez financiado","Sin comisión de activación de la cuenta financiada","Descuentos por lote: la quinta cuenta es gratis","Cuentas Instant disponibles, sin evaluación"],"verdict_card":{"title":"Para quién sí, y para quién no","body":"FuturesElite apuesta por condiciones generosas una vez financiado: 90 % de reparto, sin regla de consistencia, cobro diario. A cambio, la firma es joven, no está regulada y solo publica una de sus cuatro tarifas.","points":["Un reparto alto y cobros frecuentes, sin esperar a un vencimiento","Una evaluación sin límite de pérdida diaria, que deja respirar","Una cuenta financiada que se abre sin comisión de activación","La posibilidad de acumular hasta diez cuentas en paralelo"]},"program_guide":{"title":"El programa Elite","intro":"Elite es el único programa con tarifa pública. Nitro, Prime e Instant existen en el checkout, pero sus precios no se muestran.","options":[{"name":"Elite","badge":"Tarifa pública","summary":"Una evaluación de una etapa, un drawdown al cierre del día, sin límite de pérdida diaria y 90 % de reparto una vez financiado.","points":["Objetivo del 5 %","Sin límite de pérdida diaria","3 días mínimos de trading","Sin comisión de activación"]}]},"key_rules":{"title":"Las reglas que deciden","intro":"Lo que de verdad distingue a FuturesElite de otras firmas de futuros.","rules":[{"title":"Sin límite de pérdida diaria","detail":"Ni durante la evaluación ni una vez financiado. El riesgo lo acota únicamente la Maximum Loss Limit, recalculada al cierre de cada día. Es el argumento principal de la firma, no un dato que falte."},{"title":"Drawdown al cierre del día","detail":"El límite se actualiza una vez al día sobre el saldo de cierre, no de forma continua. Una posición en pérdida flotante no dispara el límite hasta que cierra el día."},{"title":"Sin regla de consistencia una vez financiado","detail":"La regla se aplica durante la evaluación y desaparece en la cuenta financiada. La página de venta muestra dos cifras juntas, 40 % y 50 %, sin decir cuál rige: pendiente de confirmar con el socio."},{"title":"Sin comisión de activación","detail":"Superar la evaluación basta para abrir la cuenta financiada. Las cuotas de reset sí existen: de 79 $ a 229 $ según el tamaño."}],"more":["Cobros disponibles cada día una vez financiado","6 días mínimos de trading antes de un cobro","Sin colchón de beneficio exigido","Siete plataformas a elegir, entre ellas Tradovate y NinjaTrader","La quinta cuenta de un lote es gratis"]},"journey":{"title":"Qué ocurre después de pagar","intro":"Una sola etapa de evaluación y la cuenta financiada se abre de inmediato.","steps":[{"title":"Evaluación","detail":"Alcanzar el objetivo de beneficio sin romper la Maximum Loss Limit, en al menos 3 días de trading. Sin límite de tiempo."},{"title":"Cuenta financiada","detail":"Se abre al superarla, sin comisión de activación. La regla de consistencia desaparece en esta etapa."},{"title":"Cobros","detail":"Disponibles cada día, tras 6 días de trading, dentro del tope por solicitud: 1.000 $ en un 25K, hasta 3.000 $ en un 150K."},{"title":"Acumular cuentas","detail":"Elite cuenta dentro de un límite común de 5 cuentas financiadas junto a Custom, Instant y Nitro. El techo global es de 10 cuentas financiadas activas, y Nitro por sí solo se limita a 3. Comprar un lote no eleva esos límites."}]},"cost_timeline":{"title":"Lo que vas a pagar","intro":"Los costes no llegan todos al mismo tiempo.","steps":[{"label":"Al comprar","title":"Cuota única","detail":"De 95 $ para un 25K a 353 $ para un 150K, antes de descuento. Sin suscripción."},{"label":"Si fallas","title":"Reset opcional","detail":"De 79 $ en un 25K a 229 $ en un 150K. Volver a empezar nunca es obligatorio."},{"label":"Al superarlo","title":"Sin comisión de activación","detail":"La cuenta financiada se abre sin ningún pago adicional."},{"label":"Al cobrar","title":"Tope por solicitud","detail":"De 1.000 $ a 3.000 $ según el tamaño de la cuenta, con el 90 % para ti."}]}},"pt":{"headquarters":"Corso G. Matteotti 61, Latina 04100, Itália","regulation_details":"Quantum SRL, Corso G. Matteotti 61, Latina 04100, Itália, n.º 03095010595. Sem licença de qualquer regulador financeiro. Contas demo, resultados hipotéticos.","drawdown_type":"Fim do dia","time_limit":"Sem limite de tempo","payout_frequency":"a pedido, diariamente depois de financiado","assets":["Futuros"],"included_items":["Diário de negociação e painel de análise","Sem taxa de ativação da conta financiada","Sete plataformas à escolha"],"pros":["90 % de partilha no programa Elite","Drawdown ao fecho do dia, sem qualquer limite de perda diária","Sem regra de consistência depois de financiado","Sem taxa de ativação da conta financiada","Levantamentos possíveis todos os dias depois de financiado","Descontos por lote: a quinta conta é grátis"],"cons":["Sem licença de qualquer regulador financeiro","Contas demo, resultados hipotéticos","3 dias mínimos de negociação em avaliação, 6 depois de financiado","Teto de levantamento por pedido, de 1 000 $ a 3 000 $ consoante o tamanho","As tabelas Nitro, Prime e Instant não são públicas"],"special_features":["90 % de partilha no programa Elite","Drawdown ao fecho do dia, sem limite de perda diária","Sem regra de consistência depois de financiado","Sem taxa de ativação da conta financiada","Descontos por lote: a quinta conta é grátis","Contas Instant disponíveis, sem avaliação"],"verdict_card":{"title":"Para quem serve, e para quem não","body":"A FuturesElite aposta em condições generosas depois de financiado: 90 % de partilha, sem regra de consistência, levantamento diário. Em troca, a firma é jovem, não é regulada e publica apenas uma das suas quatro tabelas.","points":["Uma partilha elevada e levantamentos frequentes, sem esperar por um prazo","Uma avaliação sem limite de perda diária, que deixa respirar","Uma conta financiada que abre sem taxa de ativação","A possibilidade de acumular até dez contas em paralelo"]},"program_guide":{"title":"O programa Elite","intro":"O Elite é o único programa com tabela pública. Nitro, Prime e Instant existem no checkout, mas os seus preços não são mostrados.","options":[{"name":"Elite","badge":"Tabela pública","summary":"Uma avaliação de uma etapa, um drawdown ao fecho do dia, sem limite de perda diária e 90 % de partilha depois de financiado.","points":["Objetivo de 5 %","Sem limite de perda diária","3 dias mínimos de negociação","Sem taxa de ativação"]}]},"key_rules":{"title":"As regras que decidem","intro":"O que distingue realmente a FuturesElite das outras firmas de futuros.","rules":[{"title":"Sem limite de perda diária","detail":"Nem durante a avaliação, nem depois de financiado. O risco é limitado apenas pela Maximum Loss Limit, recalculada ao fecho de cada dia. É o argumento principal da firma, não um dado em falta."},{"title":"Drawdown ao fecho do dia","detail":"O limite atualiza-se uma vez por dia sobre o saldo de fecho, não em contínuo. Uma posição em perda latente não aciona portanto o limite enquanto o dia não fechar."},{"title":"Sem regra de consistência depois de financiado","detail":"A regra aplica-se durante a avaliação e desaparece na conta financiada. A página de venda mostra dois valores lado a lado, 40 % e 50 %, sem dizer qual vale: a confirmar com o parceiro."},{"title":"Sem taxa de ativação","detail":"Passar a avaliação basta para abrir a conta financiada. As taxas de reset, essas, existem: de 79 $ a 229 $ consoante o tamanho."}],"more":["Levantamentos possíveis todos os dias depois de financiado","6 dias mínimos de negociação antes de um levantamento","Sem margem de lucro exigida","Sete plataformas à escolha, entre elas Tradovate e NinjaTrader","A quinta conta de um lote é grátis"]},"journey":{"title":"O que acontece depois do pagamento","intro":"Uma só etapa de avaliação e a conta financiada abre de imediato.","steps":[{"title":"Avaliação","detail":"Atingir o objetivo de lucro sem ultrapassar a Maximum Loss Limit, em pelo menos 3 dias de negociação. Sem limite de tempo."},{"title":"Conta financiada","detail":"Aberta assim que passa, sem taxa de ativação. A regra de consistência desaparece nesta etapa."},{"title":"Levantamentos","detail":"Possíveis todos os dias, após 6 dias de negociação, dentro do teto por pedido: 1 000 $ num 25K, até 3 000 $ num 150K."},{"title":"Acumular contas","detail":"O Elite conta dentro de um limite comum de 5 contas financiadas com Custom, Instant e Nitro. O teto global é de 10 contas financiadas ativas, e o Nitro sozinho limita-se a 3. Comprar um lote não aumenta esses limites."}]},"cost_timeline":{"title":"O que vai pagar","intro":"Os custos não chegam todos ao mesmo tempo.","steps":[{"label":"Na compra","title":"Taxa única","detail":"De 95 $ para um 25K a 353 $ para um 150K, antes de desconto. Sem subscrição."},{"label":"Em caso de falha","title":"Reset opcional","detail":"De 79 $ num 25K a 229 $ num 150K. Recomeçar nunca é obrigatório."},{"label":"Ao passar","title":"Sem taxa de ativação","detail":"A conta financiada abre sem qualquer pagamento adicional."},{"label":"No levantamento","title":"Teto por pedido","detail":"De 1 000 $ a 3 000 $ consoante o tamanho da conta, com 90 % para si."}]}},"ar":{"headquarters":"Corso G. Matteotti 61، لاتينا 04100، إيطاليا","regulation_details":"Quantum SRL، Corso G. Matteotti 61، لاتينا 04100، إيطاليا، رقم 03095010595. لا ترخيص من أي جهة تنظيمية مالية. حسابات تجريبية، ونتائج افتراضية.","drawdown_type":"نهاية اليوم","time_limit":"بلا حد زمني","payout_frequency":"عند الطلب، يوميًا بعد التمويل","assets":["العقود الآجلة"],"included_items":["دفتر تداول ولوحة تحليلات","لا رسوم تفعيل للحساب المموَّل","سبع منصات للاختيار بينها"],"pros":["تقاسم 90 % في برنامج Elite","تراجع يُحسب في نهاية اليوم، دون أي حد للخسارة اليومية","لا قاعدة انتظام بعد التمويل","لا رسوم تفعيل للحساب المموَّل","إمكان السحب يوميًا بعد التمويل","خصومات على الحزم: الحساب الخامس مجاني"],"cons":["لا ترخيص من أي جهة تنظيمية مالية","حسابات تجريبية، ونتائج افتراضية","3 أيام تداول كحد أدنى أثناء التقييم، و6 بعد التمويل","سقف للسحب في كل طلب، من 1,000 $ إلى 3,000 $ حسب الحجم","أسعار برامج Nitro وPrime وInstant غير معلنة"],"special_features":["تقاسم 90 % في برنامج Elite","تراجع يُحسب في نهاية اليوم، دون حد للخسارة اليومية","لا قاعدة انتظام بعد التمويل","لا رسوم تفعيل للحساب المموَّل","خصومات على الحزم: الحساب الخامس مجاني","حسابات Instant متاحة، دون تقييم"],"verdict_card":{"title":"لمن تناسب، ولمن لا","body":"تراهن FuturesElite على شروط سخية بعد التمويل: تقاسم 90 %، ولا قاعدة انتظام، وسحب يومي. في المقابل، الشركة حديثة وغير خاضعة للتنظيم، ولا تنشر سوى واحدة من قوائم أسعارها الأربع.","points":["نسبة تقاسم مرتفعة وسحوبات متكررة، دون انتظار موعد","تقييم بلا حد للخسارة اليومية، يترك مجالًا للتنفّس","حساب مموَّل يُفتح دون رسوم تفعيل","إمكان تشغيل حتى عشرة حسابات بالتوازي"]},"program_guide":{"title":"برنامج Elite","intro":"Elite هو البرنامج الوحيد الذي تُنشر قائمة أسعاره. أما Nitro وPrime وInstant فهي متاحة عند الدفع، لكن أسعارها غير معروضة.","options":[{"name":"Elite","badge":"أسعار معلنة","summary":"تقييم من مرحلة واحدة، وتراجع يُحسب في نهاية اليوم، ودون حد للخسارة اليومية، وتقاسم 90 % بعد التمويل.","points":["هدف ربح 5 %","لا حد للخسارة اليومية","3 أيام تداول كحد أدنى","لا رسوم تفعيل"]}]},"key_rules":{"title":"القواعد التي تحسم الاختيار","intro":"ما يميّز FuturesElite فعلًا عن غيرها من شركات العقود الآجلة.","rules":[{"title":"لا حد للخسارة اليومية","detail":"لا أثناء التقييم ولا بعد التمويل. يُضبط الخطر بحدّ الخسارة الأقصى وحده، ويُعاد حسابه في نهاية كل يوم. وهذه حجة الشركة الأساسية، لا معلومة ناقصة."},{"title":"تراجع يُحسب في نهاية اليوم","detail":"يتحدّث الحد مرة واحدة يوميًا على رصيد الإغلاق، لا باستمرار. لذلك لا تُفعِّل الصفقةُ الخاسرة عائمًا الحدَّ ما لم يُغلَق اليوم."},{"title":"لا قاعدة انتظام بعد التمويل","detail":"تنطبق القاعدة أثناء التقييم ثم تختفي على الحساب المموَّل. وتعرض صفحة البيع رقمين متجاورين، 40 % و50 %، دون بيان أيّهما ينطبق: يلزم التأكد من الشريك."},{"title":"لا رسوم تفعيل","detail":"اجتياز التقييم يكفي لفتح الحساب المموَّل. أما رسوم إعادة التعيين فموجودة: من 79 $ إلى 229 $ حسب الحجم."}],"more":["إمكان السحب يوميًا بعد التمويل","6 أيام تداول كحد أدنى قبل السحب","لا يُشترط احتياطي أرباح","سبع منصات للاختيار بينها، منها Tradovate وNinjaTrader","الحساب الخامس في الحزمة مجاني"]},"journey":{"title":"ما يحدث بعد الدفع","intro":"مرحلة تقييم واحدة، ثم يُفتح الحساب المموَّل فورًا.","steps":[{"title":"التقييم","detail":"بلوغ هدف الربح دون تجاوز حدّ الخسارة الأقصى، على مدى 3 أيام تداول على الأقل. بلا حد زمني."},{"title":"الحساب المموَّل","detail":"يُفتح فور النجاح، دون رسوم تفعيل. وتختفي قاعدة الانتظام عند هذه المرحلة."},{"title":"السحوبات","detail":"ممكنة يوميًا، بعد 6 أيام تداول، في حدود السقف لكل طلب: 1,000 $ على حساب 25K، وحتى 3,000 $ على حساب 150K."},{"title":"تعدد الحسابات","detail":"يقتصر Elite على 5 حسابات مموَّلة. وبضم برنامج بالحجم نفسه، يمكن بلوغ 10 حسابات بالتوازي."}]},"cost_timeline":{"title":"ما ستدفعه","intro":"التكاليف لا تأتي كلها في اللحظة نفسها.","steps":[{"label":"عند الشراء","title":"رسوم لمرة واحدة","detail":"من 95 $ لحساب 25K إلى 353 $ لحساب 150K، قبل الخصم. بلا اشتراك."},{"label":"عند الإخفاق","title":"إعادة تعيين اختيارية","detail":"من 79 $ على حساب 25K إلى 229 $ على حساب 150K. والبدء من جديد ليس إلزاميًا أبدًا."},{"label":"عند النجاح","title":"لا رسوم تفعيل","detail":"يُفتح الحساب المموَّل دون أي دفعة إضافية."},{"label":"عند السحب","title":"سقف لكل طلب","detail":"من 1,000 $ إلى 3,000 $ حسب حجم الحساب، مع 90 % لك."}]}},"hi":{"headquarters":"Corso G. Matteotti 61, लातीना 04100, इटली","regulation_details":"Quantum SRL, Corso G. Matteotti 61, लातीना 04100, इटली, क्रमांक 03095010595। किसी वित्तीय नियामक का लाइसेंस नहीं। डेमो खाते, काल्पनिक परिणाम।","drawdown_type":"दिन के अंत में","time_limit":"कोई समय-सीमा नहीं","payout_frequency":"अनुरोध पर, फ़ंडेड होने के बाद प्रतिदिन","assets":["फ़्यूचर्स"],"included_items":["ट्रेडिंग जर्नल और एनालिटिक्स डैशबोर्ड","फ़ंडेड खाते पर कोई सक्रियण शुल्क नहीं","चुनने के लिए सात प्लेटफ़ॉर्म"],"pros":["Elite प्रोग्राम पर 90 % हिस्सेदारी","दिन के अंत का ड्रॉडाउन, बिना किसी दैनिक हानि सीमा के","फ़ंडेड होने के बाद कोई कंसिस्टेंसी नियम नहीं","फ़ंडेड खाते पर कोई सक्रियण शुल्क नहीं","फ़ंडेड होने के बाद हर दिन पेआउट संभव","बंडल छूट: पाँचवाँ खाता मुफ़्त"],"cons":["किसी वित्तीय नियामक का लाइसेंस नहीं","डेमो खाते, काल्पनिक परिणाम","मूल्यांकन में कम से कम 3 ट्रेडिंग दिवस, फ़ंडेड होने पर 6","प्रति अनुरोध पेआउट सीमा, आ